{* Code generated by xgen. DO NOT EDIT.
    Source: xgen/specs/organisms/store-locations.json
    The stores of a shop: name, a badge of its kind (pickup or store only), address, hours, phone, a note and the services. Axes: layout (cards, list: one row per store, map: compact cards beside a map picture), tone.
    Props (p): id, title, lead, stores, kinds, labels, layout, tone, landmarkLabel. *}
{var $v_id = ($p['id'] ?? null)}
{var $v_title = ($p['title'] ?? null)}
{var $v_lead = ($p['lead'] ?? '')}
{var $v_stores = ($p['stores'] ?? null)}
{var $v_kinds = ($p['kinds'] ?? null)}
{var $v_labels = ($p['labels'] ?? null)}
{var $v_layout = ($p['layout'] ?? 'cards')}
{var $v_tone = ($p['tone'] ?? 'default')}
{var $v_landmarkLabel = ($p['landmarkLabel'] ?? null)}
{capture $c_18}
  {capture $c_17}
    {capture $c_15}
      {foreach ui_l($v_stores) as $v_s}
        {capture $c_14}
          {capture $c_3}
            {capture $c_1}
              {=ui_text(ui_at($v_kinds, ui_get($v_s, ['kind'])))}
            {/capture}
            {=ui_include('ui/badge/badge.latte', ['p' => ['Variant' => 'outline', 'Size' => 'default', 'Class' => 'w-fit'], 'children' => $c_1])|noescape}
            {capture $c_2}
              {=ui_text(ui_get($v_s, ['name']))}
            {/capture}
            {=ui_include('ui/title/title.latte', ['p' => ['As' => ui_i(3), 'Size' => 'lg', 'Weight' => 'bold'], 'children' => $c_2])|noescape}
          {/capture}
          {=ui_include('ui/stack/stack.latte', ['p' => ['Gap' => '2'], 'children' => $c_3])|noescape}
          {capture $c_10}
            {capture $c_5}
              {=ui_include('ui/lucide-icon/lucide-icon.latte', ['p' => ['Name' => 'map-pin', 'Size' => 16]])|noescape}
              {capture $c_4}
                {=ui_text(ui_get($v_s, ['address']))}
              {/capture}
              {=ui_include('ui/inline/inline.latte', ['p' => [], 'children' => $c_4])|noescape}
            {/capture}
            {=ui_include('ui/list/list-item.latte', ['p' => ['Class' => 'flex items-center gap-2'], 'children' => $c_5])|noescape}
            {capture $c_7}
              {=ui_include('ui/lucide-icon/lucide-icon.latte', ['p' => ['Name' => 'clock', 'Size' => 16]])|noescape}
              {capture $c_6}
                {=ui_text(ui_get($v_s, ['hours']))}
              {/capture}
              {=ui_include('ui/inline/inline.latte', ['p' => [], 'children' => $c_6])|noescape}
            {/capture}
            {=ui_include('ui/list/list-item.latte', ['p' => ['Class' => 'flex items-center gap-2'], 'children' => $c_7])|noescape}
            {capture $c_9}
              {=ui_include('ui/lucide-icon/lucide-icon.latte', ['p' => ['Name' => 'phone', 'Size' => 16]])|noescape}
              {capture $c_8}
                {=ui_text(ui_nbsp(ui_get($v_s, ['phone'])))}
              {/capture}
              {=ui_include('ui/link/link.latte', ['p' => ['Href' => ui_s(ui_tpl('tel:{0}', [ui_get($v_s, ['phone'])])), 'Variant' => 'default'], 'children' => $c_8])|noescape}
            {/capture}
            {=ui_include('ui/list/list-item.latte', ['p' => ['Class' => 'flex items-center gap-2'], 'children' => $c_9])|noescape}
          {/capture}
          {=ui_include('ui/list/list.latte', ['p' => ['Tag' => 'ul', 'Class' => ui_s((ui_t(ui_eq($v_layout, 'list')) ? 'flex flex-wrap gap-x-8 gap-y-2 text-sm' : 'flex flex-col gap-2 text-sm'))], 'children' => $c_10])|noescape}
          {if ui_t(ui_eq($v_layout, 'cards'))}
            {capture $c_11}
              {=ui_text(ui_get($v_s, ['note']))}
            {/capture}
            {=ui_include('ui/text/text.latte', ['p' => ['Size' => 'sm', 'Class' => 'text-muted-foreground'], 'children' => $c_11])|noescape}
            {capture $c_13}
              {foreach ui_l(ui_get($v_s, ['services'])) as $v_v}
                {capture $c_12}
                  {=ui_text($v_v)}
                {/capture}
                {=ui_include('ui/badge/badge.latte', ['p' => ['Variant' => 'secondary', 'Size' => 'default'], 'children' => $c_12])|noescape}
              {/foreach}
            {/capture}
            {=ui_include('ui/group/group.latte', ['p' => ['Gap' => '2', 'Class' => 'flex-wrap'], 'children' => $c_13])|noescape}
          {/if}
        {/capture}
        {=ui_include('ui/stack/stack.latte', ['p' => ['Gap' => '4', 'Class' => ui_s((ui_t(ui_eq($v_layout, 'list')) ? 'border-b border-border pb-4' : 'rounded bg-card inset-ring inset-ring-border p-6')), 'Attrs' => ui_attrs(['data-testid', 'item'])], 'children' => $c_14])|noescape}
      {/foreach}
    {/capture}
    {=ui_include('ui/box/box.latte', ['p' => ['Class' => ui_s((ui_t(ui_eq($v_layout, 'cards')) ? 'grid grid-cols-1 gap-4 md:grid-cols-2' : 'flex flex-col gap-4')), 'Attrs' => ui_attrs(['data-testid', 'items'])], 'children' => $c_15])|noescape}
    {if ui_t(ui_eq($v_layout, 'map'))}
      {capture $c_16}
        {=ui_include('blocks/media-frame.latte', ['p' => ['alt' => ui_get($v_labels, ['map']), 'ratio' => '1/1']])|noescape}
      {/capture}
      {=ui_include('ui/box/box.latte', ['p' => ['Class' => 'md:sticky md:top-8'], 'children' => $c_16])|noescape}
    {/if}
  {/capture}
  {=ui_include('ui/box/box.latte', ['p' => ['Class' => ui_s(ui_cnv(['grid grid-cols-1 gap-8', (ui_t(ui_eq($v_layout, 'map')) ? 'items-start md:grid-cols-2' : '')]))], 'children' => $c_17])|noescape}
{/capture}
{=ui_include('blocks/section-frame.latte', ['p' => ['id' => $v_id, 'title' => $v_title, 'lead' => $v_lead, 'tone' => $v_tone, 'landmarkLabel' => $v_landmarkLabel], 'children' => $c_18])|noescape}
